<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/StorySimulationBatchService.php';$max=1;foreach(array_slice($argv,1)as$arg)if(preg_match('/^--max=(\d+)$/',$arg,$m))$max=max(1,min(100,(int)$m[1]));$processed=0;try{while($processed<$max){$batch=StorySimulationBatchService::processNext();if(!$batch)break;$processed++;echo 'Batch '.$batch['simulation_review_batch_id'].': '.$batch['status'].' '.$batch['completed_runs'].'/'.$batch['requested_runs'].PHP_EOL;}echo 'Processed '.$processed.' simulation review run(s).'.PHP_EOL;exit(0);}catch(Throwable $e){fwrite(STDERR,'Simulation review worker failed: '.$e->getMessage().PHP_EOL);exit(1);}
